(() => {
  const front = window.PRISMA_DATA.fronts.find((item) => item.slug === document.body.dataset.front);
  if (!front) return;
  document.title = `${front.title} — Prisma`;
  const serviceMarkup = front.services.map((service, index) => `<article class="service-card" data-reveal><span class="service-index">${String(index + 1).padStart(2, "0")}</span><div class="service-icon service-icon--${service.visual}" aria-hidden="true"><span></span><span></span><span></span></div><h3>${service.title}</h3><p>${service.description}</p><ul>${service.tags.map((tag) => `<li>${tag}</li>`).join("")}</ul></article>`).join("");
  document.querySelector("[data-front-content]").innerHTML = `<article class="front-page front-page--${front.slug} front-page--${front.visual}"><header class="section front-hero"><div class="front-hero__glow" aria-hidden="true"></div><div class="container front-hero__grid"><div class="front-hero__copy" data-reveal><a class="back-link" href="/#frentes"><span>←</span> Ver as duas frentes</a><p class="eyebrow"><span></span>${front.eyebrow}</p><h1>${front.headline} <em>${front.emphasis}</em></h1><p class="front-hero__lead">${front.summary}</p><div class="hero-actions"><a class="button" href="/#contato">${front.cta} <span>↗</span></a><a class="text-link" href="#cases">Ver cases <span>↓</span></a></div></div><div class="front-emblem front-emblem--${front.visual}" role="img" aria-label="Composição abstrata da frente de ${front.title}" data-reveal><span class="front-emblem__label">Prisma / ${front.title}</span><div class="front-emblem__shape"><i></i><i></i><i></i><i></i></div><span class="front-emblem__number">${front.slug === "marketing" ? "01" : "02"}</span></div></div></header><section class="front-statement"><div class="container front-statement__inner" data-reveal><span>${front.title}</span><p>${front.description}</p></div></section><section class="section front-services" id="servicos"><div class="container"><div class="section-heading" data-reveal><div><p class="eyebrow"><span></span>O que fazemos</p><h2>Competências organizadas para <em>cada contexto.</em></h2></div><p>Soluções combinadas de acordo com o desafio, o momento e as prioridades de cada projeto.</p></div><div class="service-grid front-service-grid">${serviceMarkup}</div></div></section><section class="section portfolio-section front-portfolio" id="cases"><div class="container"><div class="section-heading section-heading--portfolio" data-reveal><div><p class="eyebrow"><span></span>Cases / ${front.title}</p><h2>Projetos desta frente <em>em movimento.</em></h2></div><p>Apenas trabalhos reais e autorizados são publicados nesta área.</p></div><div class="project-grid project-grid--placeholders" data-project-list="${front.slug}"></div><p class="portfolio-note"><span>i</span> Nenhum cliente, resultado ou número fictício foi utilizado.</p></div></section><aside class="section cross-front"><div class="container cross-front__inner" data-reveal><div><p class="eyebrow"><span></span>A outra face da Prisma</p><h2>Conheça também <em>${front.slug === "marketing" ? "Tecnologia" : "Marketing"}.</em></h2><p>Estratégia, comunicação e engenharia conectadas para fazer cada solução avançar.</p></div><a class="button" href="/frentes/${front.slug === "marketing" ? "tecnologia" : "marketing"}/">Conhecer a frente <span>→</span></a></div></aside></article>`;
})();
